import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.DoCD98hS.js";const h=JSON.parse('{"title":"wujie 2 · 页签核心与异构子应用主微前端模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/wujie.md","filePath":"modules/catalog/wujie.md","lastUpdated":1795057090000}'),a={name:"modules/catalog/wujie.md"};function i(r,e,l,u,p,s){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="wujie-2-·-页签核心与异构子应用主微前端模板" tabindex="-1">wujie 2 · 页签核心与异构子应用主微前端模板 <a class="header-anchor" href="#wujie-2-·-页签核心与异构子应用主微前端模板" aria-label="Permalink to &quot;wujie 2 · 页签核心与异构子应用主微前端模板&quot;">​</a></h1><p>页签核心由框架无关的 <code>libs-wujie2-tabs-core</code> 管理，Vue 3 宿主用无头组件渲染自己的 Tab 栏。主应用（Vue 3 / CLI 5）通过 <code>wujie-vue3</code> 以 <code>alive</code> 模式挂载 4 个异构子应用，覆盖 Vue 3 CLI 5、Vue 3 Vite、Vue 2.7 CLI 4 与 React 18 Vite 三种框架、两种构建链。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-wujie2-tabs-core</code></td><td>框架无关层：页签状态机（runtime）、页签 id 编解码（<code>tab-id</code>）、页面级保活判定（<code>page-cache</code>），不持有 Wujie 实例</td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-vue3</code></td><td>Vue 3 适配层，提供无头 <code>WujieTabBar</code> 与 <code>useWujieTabs</code></td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-vue2</code></td><td>Vue 2.7 适配层，API 与 Vue 3 版一致，组件销毁时自动退订</td></tr><tr><td><code>@melt-js/libs-wujie2-tabs-react</code></td><td>React 18 适配层，<code>useWujieTabs</code> 基于 <code>useSyncExternalStore</code>，附 <code>children</code> 渲染函数的无头组件</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-cli5-main</code></td><td>Vue 3 主应用（Vue CLI 5 / webpack 5），托管 4 个子应用并维护菜单与页签</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-cli5-app1</code></td><td>Vue 3 子应用（Vue CLI 5，Element Plus / Ant Design Vue 页面）</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue3-vite-app2</code></td><td>Vue 3 子应用（Vite）</td></tr><tr><td><code>@melt-js/tpl-wujie2-vue2-cli4-app3</code></td><td>Vue 2.7 子应用（Vue CLI 4 / webpack 4，Element UI）</td></tr><tr><td><code>@melt-js/tpl-wujie2-react-vite-app4</code></td><td>React 18 子应用（Vite 6，Ant Design）</td></tr></tbody></table><p>仅兼容 wujie 2，不做 wujie 1 兼容。四个 <code>libs-wujie2-tabs-*</code> 为纯构建产物，不单独起服务。</p><p>分层与 qiankun 页签库一致：core 只做框架无关的状态与判定，适配层负责把状态接进各自框架的响应式系统并暴露无头组件，路由、沙箱生命周期与样式留在宿主模板。区别在于 qiankun 的页面缓存由 core 的 <code>page-cache</code> 直接控制子应用容器，wujie 的 <code>alive</code> 只到应用级，页面级不保活的执行点是子应用渲染层，所以 core 提供 <code>shouldMountPage</code> 判定、由宿主把激活页签经 <code>bus</code> 广播给子应用执行。</p><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>链接按各包 <code>package.json</code> 的 <code>unpkg</code> 入口生成，站点按当前部署域名改写为对应镜像；页面内容随包发布更新。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-wujie2-vue3-cli5-main</code></td><td><a href="https://unpkg.com/@melt-js/tpl-wujie2-vue3-cli5-main/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue3-cli5-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-wujie2-vue3-cli5-app1/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue3-vite-app2</code></td><td><a href="https://unpkg.com/@melt-js/tpl-wujie2-vue3-vite-app2/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-vue2-cli4-app3</code></td><td><a href="https://unpkg.com/@melt-js/tpl-wujie2-vue2-cli4-app3/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-wujie2-react-vite-app4</code></td><td><a href="https://unpkg.com/@melt-js/tpl-wujie2-react-vite-app4/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><p>子应用单独打开时是独立页面，只有通过主应用进入才能验证页签、保活与路由同步。</p><h2 id="本地联调" tabindex="-1">本地联调 <a class="header-anchor" href="#本地联调" aria-label="Permalink to &quot;本地联调&quot;">​</a></h2><p>在 workspace 根执行 <code>pnpm wj2:dev</code> 并行启动主应用与 4 个子应用，或在各包目录单独执行 <code>pnpm dev</code>。端口按下表，主应用需先有子应用入口才能挂载。</p><table tabindex="0"><thead><tr><th>包</th><th>开发端口</th><th>预览端口</th></tr></thead><tbody><tr><td><code>tpl-wujie2-vue3-cli5-main</code></td><td>50390</td><td>50395</td></tr><tr><td><code>tpl-wujie2-vue3-cli5-app1</code></td><td>50171</td><td>50231</td></tr><tr><td><code>tpl-wujie2-vue3-vite-app2</code></td><td>50172</td><td>50232</td></tr><tr><td><code>tpl-wujie2-vue2-cli4-app3</code></td><td>50173</td><td>50233</td></tr><tr><td><code>tpl-wujie2-react-vite-app4</code></td><td>50174</td><td>50234</td></tr></tbody></table><p>构建与预览：<code>pnpm wj2:build</code> 依次构建 4 个子应用，再执行主应用 <code>build:local</code>；<code>pnpm wj2:preview</code> 预览主应用。页签库用 <code>pnpm wj2:tabs:build</code>、<code>pnpm wj2:tabs:test</code> 单独构建与测试。</p><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>core：<code>createWujieTabs({ initialTabs })</code></td><td>创建页签管理器，<code>pinned</code> 页签在关闭操作中始终保留</td></tr><tr><td>core：<code>open(tab)</code></td><td>按 <code>id</code> 去重并激活；建议用 Wujie 的 <code>name</code> 作 <code>id</code>，完整路径、query、hash 存在 <code>fullPath</code></td></tr><tr><td>core：<code>activate(id)</code> / <code>activate(null)</code></td><td>切换已打开页签，传 <code>null</code> 清除选中</td></tr><tr><td>core：<code>getState()</code> / <code>subscribe(listener)</code></td><td>只读快照与变更订阅，<code>subscribe</code> 返回取消订阅函数</td></tr><tr><td>core：<code>close(id)</code> / <code>closeOthers(id)</code> / <code>closeAll()</code></td><td>关闭单个或批量关闭；关闭当前项时优先选右侧相邻，其次左侧</td></tr><tr><td>core：<code>getCloseFallback(id)</code></td><td>提前取得关闭当前页签后的候选项</td></tr><tr><td>Vue 3：<code>WujieTabBar</code></td><td>无头组件，只渲染默认插槽，DOM、样式与键盘交互由宿主决定</td></tr><tr><td>Vue 3：<code>useWujieTabs(manager)</code></td><td>在 <code>setup</code> 内取得只读响应式快照，操作仍走同一个 manager</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>WujieTabBar</code>（Vue 3）</td><td>默认插槽暴露 <code>tabs</code>、<code>activeId</code>、<code>activate</code>、<code>close</code>、<code>closeOthers</code>、<code>closeAll</code></td></tr></tbody></table><p>页面级 Tab 栏、菜单与 API 演示页都在主应用内维护，不作为独立组件导出。</p><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p>主应用 <code>app.use(WujieVue)</code> 注册 <code>wujie-vue3</code>，按子应用清单逐个 <code>preloadApp({ name, url, alive: true })</code> 预取资源，挂载视图同步使用 <code>alive</code>，切回时保留子应用状态。子应用清单集中在 <code>src/wujie/apps.js</code>，入口来自 <code>.env</code> 的 <code>VUE_APP_APP1_ENTRY</code> ~ <code>VUE_APP_APP4_ENTRY</code>，本地 / SFTP / GitHub / unpkg 四档由根环境同步按目标注入。</p><p>页签侧先 <code>createWujieTabs</code> 建立状态，<code>id</code> 对齐子应用 <code>name</code>，<code>fullPath</code> 记录含 query 与 hash 的完整路径；宿主完成路由导航后再更新或关闭页签，避免守卫拦截后留下错误选中态。子应用内部路由需经 <code>route-bridge</code> 同步菜单选中、Tab 标题与浏览器前进后退；关闭页签会销毁对应 Wujie 实例，再次打开重新挂载。</p><p>子应用按各自框架正常导出应用即可，<code>alive</code> 由宿主配置决定，不需要在子应用内声明 Wujie 生命周期。需要注意 <code>alive</code> 是<strong>应用级</strong>开关：它保证子应用实例在页签切换时不被销毁，但无法区分同一个子应用下的不同页面。模板因此补了一层页面级方案——宿主 <code>tabs.js</code> 在页签变化时通过 <code>bus</code> 广播 <code>wujie:tab:active</code>（携带当前激活页签属于哪个应用、哪个 <code>path</code>），子应用据此渲染：标记 <code>keepAlive: false</code> 的页面只在所属页签激活时挂载，切走即卸载、切回重建，观感与 qiankun 的页面级 <code>keepAlive</code> 一致。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>主应用基于 wujie 2 的 Vue 3 使用方式（<code>wujie-vue3</code> + <code>bus</code>），菜单与路由统一由主应用维护，并标记各页面是否保活。主应用侧对齐 qiankun 模板的示例结构，含首页、关于（带 query）、用户、临时表单（不保活）、页面守卫演示、Wujie API 演示六项，其中“页面守卫演示”展示 <code>router.beforeEach</code> 的二次确认拦截。四个子应用各自提供“关于 / 用户 / 临时表单（不保活）”三个页面，每个子应用都能就地对照保活与不保活的状态差异：保活页切换页签后输入仍在，临时表单切走后重新创建、输入清空。页面状态用输入探针验证，主应用“Wujie API 演示”页覆盖 Tab 操作、主子应用路由同步与 <code>bus</code> 双向通信。</p><p>页签库为本仓库自研（<code>libs-wujie2-tabs-*</code>），不依赖 wujie 官方示例的页签实现。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><p>以下先列改造顺序，具体文件、配置和代码差异在实现定稿后补齐。</p><ol><li>先整理主应用的子应用清单、<code>name</code>、入口 URL 与菜单映射，确定哪些路由需要保活。</li><li>用 <code>app.use(WujieVue)</code> 注册宿主组件，以 <code>preloadApp</code> + <code>alive</code> 预取并挂载，保持预取与视图选项一致。</li><li>接入页签库：<code>createWujieTabs</code> 建立状态，<code>id</code> 用子应用 <code>name</code>，<code>fullPath</code> 保存完整路径；用 <code>WujieTabBar</code> 或自写 Tab 栏消费快照。</li><li>打通路由：宿主导航后更新页签，子应用内部路由经桥接回传，处理前进后退与多页签共用同一应用的情况。</li><li>按框架验证子应用：Vue CLI 4 项目调整 <code>publicPath</code> 与打包产物路径，Vite 项目确认跨域与入口可达，再逐项测试切页、关闭重开、刷新与卸载。</li></ol><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补主应用与 4 个子应用的职责、框架/构建链差异表。</li><li>[ ] 补页签状态、<code>fullPath</code> 同步、保活与销毁时机、<code>bus</code> 通信的完整 API。</li><li>[x] 三个适配包（Vue 3 / Vue 2.7 / React）的导出签名与最小示例，见各包 README。</li><li>[ ] 补各子应用的逐文件改造表、启动组合和部署路径。</li></ul>',32)])])}const b=t(a,[["render",i]]);export{h as __pageData,b as default};
